import type { Rect, SceneNode } from "./contracts";

export interface ImageGeometry {
  /** CSS content box, relative to the image element's unrotated corner. */
  content: Rect;
  /** Fitted image bounds, in the same coordinates as the content box. */
  object: Rect;
}

/** Resolve captured object-fit/position after capture has scaled the box,
 * border widths, padding, and position offsets with its CSS transform. */
export function imageGeometry(node: SceneNode): ImageGeometry | undefined {
  const image = node.image;
  if (!image) return undefined;
  const width = node.rect.width;
  const height = node.rect.height;
  const padding = node.layout.padding ?? [0, 0, 0, 0];
  let [top, right, bottom, left] = (["top", "right", "bottom", "left"] as const)
    .map((side, index) => {
      const border = node.paint.borders?.[side] ?? { width: node.paint.borderWidth ?? 0, style: node.paint.borderStyle ?? "solid" };
      return (["none", "hidden"].includes(border.style) ? 0 : border.width) + padding[index];
    });
  // Real CSS boxes contain their borders and padding. Bound validated scenes
  // from other producers too, so overlarge insets cannot cross or go outside
  // the element when its content box is empty.
  const horizontalScale = Math.min(1, width / (left + right || 1));
  const verticalScale = Math.min(1, height / (top + bottom || 1));
  left *= horizontalScale;
  right *= horizontalScale;
  top *= verticalScale;
  bottom *= verticalScale;
  const content = { x: left, y: top, width: Math.max(0, width - left - right), height: Math.max(0, height - top - bottom) };
  const empty = (): ImageGeometry => ({ content, object: { x: content.x, y: content.y, width: 0, height: 0 } });
  if (!content.width || !content.height) return empty();

  let objectWidth = content.width;
  let objectHeight = content.height;
  if (image.fit !== "fill") {
    const intrinsicWidth = image.intrinsicWidth * (image.scale ?? 1);
    const intrinsicHeight = image.intrinsicHeight * (image.scale ?? 1);
    if (!(intrinsicWidth > 0) || !(intrinsicHeight > 0)) return empty();
    const contain = Math.min(content.width / intrinsicWidth, content.height / intrinsicHeight);
    const scale = image.fit === "contain" ? contain
      : image.fit === "cover" ? Math.max(content.width / intrinsicWidth, content.height / intrinsicHeight)
      : image.fit === "scale-down" ? Math.min(1, contain) : 1;
    objectWidth = intrinsicWidth * scale;
    objectHeight = intrinsicHeight * scale;
  }
  return {
    content,
    object: {
      x: content.x + (content.width - objectWidth) * image.position.x.percentage + image.position.x.offset,
      y: content.y + (content.height - objectHeight) * image.position.y.percentage + image.position.y.offset,
      width: objectWidth,
      height: objectHeight
    }
  };
}
import { PROTOCOL_VERSION, SCENE_LIMITS, type AssetRef, type SceneDocument, type SceneNode } from "./contracts";
import { imageGeometry } from "./images";

function fail(message: string): never {
  throw new Error(`Invalid import scene: ${message}`);
}

function record(value: unknown, label: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) fail(`${label} must be an object.`);
  return value as Record<string, unknown>;
}

function string(value: unknown, label: string, maximum = Number.POSITIVE_INFINITY): string {
  if (typeof value !== "string" || value.length > maximum) fail(`${label} must be a string no longer than ${maximum} characters.`);
  return value;
}

function number(value: unknown, label: string, minimum = -Number.MAX_VALUE): number {
  if (typeof value !== "number" || !Number.isFinite(value) || value < minimum) fail(`${label} must be a finite number.`);
  return value;
}

function array(value: unknown, label: string, maximum: number = SCENE_LIMITS.maxLayers): unknown[] {
  if (!Array.isArray(value) || value.length > maximum) fail(`${label} must be an array with at most ${maximum} entries.`);
  return value;
}

function optionalString(value: unknown, label: string, maximum = Number.POSITIVE_INFINITY): void {
  if (value !== undefined) string(value, label, maximum);
}

function optionalNumber(value: unknown, label: string, minimum = -Number.MAX_VALUE, maximum = Number.MAX_VALUE): void {
  if (value === undefined) return;
  const parsed = number(value, label, minimum);
  if (parsed > maximum) fail(`${label} must be no greater than ${maximum}.`);
}

function optionalBoolean(value: unknown, label: string): void {
  if (value !== undefined && typeof value !== "boolean") fail(`${label} must be a boolean.`);
}

function enumValue(value: unknown, label: string, values: readonly string[]): void {
  if (value !== undefined && (typeof value !== "string" || !values.includes(value))) {
    fail(`${label} must be one of ${values.join(", ")}.`);
  }
}

function tuple(value: unknown, label: string, minimum = -Number.MAX_VALUE): void {
  if (!Array.isArray(value) || value.length !== 4) fail(`${label} must contain exactly four numbers.`);
  value.forEach((part, index) => number(part, `${label}[${index}]`, minimum));
}

// Penpot's plugin compartment does not expose a constructible TextEncoder.
// Count the UTF-8 representation directly so the safety limit is preserved
// without relying on a host-provided global.
export function utf8ByteLength(value: string): number {
  let bytes = 0;
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 0x80) bytes += 1;
    else if (code < 0x800) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff && index + 1 < value.length) {
      const next = value.charCodeAt(index + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        bytes += 4;
        index += 1;
      } else bytes += 3;
    } else bytes += 3;
  }
  return bytes;
}

function validateNode(value: unknown, index: number): asserts value is SceneNode {
  const node = record(value, `nodes[${index}]`);
  string(node.id, `nodes[${index}].id`, 200);
  if (node.parentId !== undefined) string(node.parentId, `nodes[${index}].parentId`, 200);
  array(node.children, `nodes[${index}].children`).forEach((child, childIndex) => string(child, `nodes[${index}].children[${childIndex}]`, 200));
  if (!["container", "box", "text", "image", "svg", "fallback"].includes(string(node.kind, `nodes[${index}].kind`, 30))) fail(`nodes[${index}].kind is unsupported.`);
  string(node.name, `nodes[${index}].name`, 200);
  string(node.source, `nodes[${index}].source`, 2_000);
  const rect = record(node.rect, `nodes[${index}].rect`);
  const x = number(rect.x, `nodes[${index}].rect.x`);
  if (Math.abs(x) > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].rect.x must be within ±${SCENE_LIMITS.maxDimension}.`);
  const y = number(rect.y, `nodes[${index}].rect.y`);
  if (Math.abs(y) > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].rect.y must be within ±${SCENE_LIMITS.maxDimension}.`);
  const width = number(rect.width, `nodes[${index}].rect.width`, 0);
  if (width > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].rect.width must be no greater than ${SCENE_LIMITS.maxDimension}.`);
  const height = number(rect.height, `nodes[${index}].rect.height`, 0);
  if (height > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].rect.height must be no greater than ${SCENE_LIMITS.maxDimension}.`);
  optionalNumber(node.rotation, `nodes[${index}].rotation`, -360, 360);
  number(node.zIndex, `nodes[${index}].zIndex`);
  optionalBoolean(node.zIndexAuto, `nodes[${index}].zIndexAuto`);
  validatePaint(node.paint, index);
  validateLayout(node.layout, index);
  if (node.text !== undefined) string(node.text, `nodes[${index}].text`, 100_000);
  if (node.textNoWrap !== undefined && typeof node.textNoWrap !== "boolean") fail(`nodes[${index}].textNoWrap must be a boolean.`);
  if (node.textFitScale !== undefined) {
    const scale = number(node.textFitScale, `nodes[${index}].textFitScale`, 0.01);
    if (scale > 1) fail(`nodes[${index}].textFitScale must be no greater than 1.`);
  }
  if (node.textMaxWidth !== undefined) number(node.textMaxWidth, `nodes[${index}].textMaxWidth`, 0.1);
  if (node.textStyle !== undefined) validateTextStyle(node.textStyle, index);
  if (node.assetId !== undefined) string(node.assetId, `nodes[${index}].assetId`, 200);
  if (node.image !== undefined) {
    if (node.kind !== "image" || node.assetId === undefined) fail(`nodes[${index}].image requires an image node with an assetId.`);
    validateImage(node.image, index);
    const geometry = imageGeometry(node as unknown as SceneNode)!;
    const radians = (Number(node.rotation) || 0) * Math.PI / 180;
    const object = geometry.object;
    const position = {
      x: x + object.x * Math.cos(radians) - object.y * Math.sin(radians),
      y: y + object.x * Math.sin(radians) + object.y * Math.cos(radians)
    };
    for (const amount of [position.x, position.y, object.width, object.height]) {
      if (!Number.isFinite(amount) || Math.abs(amount) > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].image fitted geometry must be within ±${SCENE_LIMITS.maxDimension}px.`);
    }
  }
  if (node.fallbackReason !== undefined) string(node.fallbackReason, `nodes[${index}].fallbackReason`, 1_000);
}

function validateImage(value: unknown, index: number): void {
  const label = `nodes[${index}].image`;
  const image = record(value, label);
  enumValue(string(image.fit, `${label}.fit`, 30), `${label}.fit`, ["fill", "contain", "cover", "none", "scale-down"]);
  for (const field of ["intrinsicWidth", "intrinsicHeight"] as const) {
    const dimension = number(image[field], `${label}.${field}`, Number.MIN_VALUE);
    if (dimension > SCENE_LIMITS.maxDimension) fail(`${label}.${field} must be no greater than ${SCENE_LIMITS.maxDimension}.`);
  }
  optionalNumber(image.scale, `${label}.scale`, Number.MIN_VALUE, SCENE_LIMITS.maxDimension);
  const position = record(image.position, `${label}.position`);
  for (const axis of ["x", "y"] as const) {
    const axisLabel = `${label}.position.${axis}`;
    const coordinate = record(position[axis], axisLabel);
    for (const field of ["percentage", "offset"] as const) {
      const amount = number(coordinate[field], `${axisLabel}.${field}`);
      if (Math.abs(amount) > SCENE_LIMITS.maxDimension) fail(`${axisLabel}.${field} must be within ±${SCENE_LIMITS.maxDimension}.`);
    }
  }
}

function validatePaint(value: unknown, index: number): void {
  const paint = record(value, `nodes[${index}].paint`);
  optionalString(paint.backgroundColor, `nodes[${index}].paint.backgroundColor`, 200);
  optionalString(paint.backgroundImage, `nodes[${index}].paint.backgroundImage`, 2_000_000);
  // Background placement arrived on main while this validation was in review.
  // These feed asset materialization, so they are bounded like other paint
  // strings rather than reaching the importer unchecked.
  for (const field of ["backgroundRepeat", "backgroundRepeatX", "backgroundRepeatY", "backgroundSize", "backgroundPosition", "backgroundPositionX", "backgroundPositionY"] as const) {
    optionalString(paint[field], `nodes[${index}].paint.${field}`, 500);
  }
  optionalString(paint.color, `nodes[${index}].paint.color`, 200);
  optionalString(paint.borderColor, `nodes[${index}].paint.borderColor`, 200);
  optionalNumber(paint.borderWidth, `nodes[${index}].paint.borderWidth`, 0, SCENE_LIMITS.maxDimension);
  optionalString(paint.borderStyle, `nodes[${index}].paint.borderStyle`, 50);
  if (paint.borders !== undefined) {
    const label = `nodes[${index}].paint.borders`;
    const borders = record(paint.borders, label);
    for (const side of ["top", "right", "bottom", "left"] as const) {
      const sideLabel = `${label}.${side}`;
      const border = record(borders[side], sideLabel);
      string(border.color, `${sideLabel}.color`, 200);
      const width = number(border.width, `${sideLabel}.width`, 0);
      if (width > SCENE_LIMITS.maxDimension) fail(`${sideLabel}.width must be no greater than ${SCENE_LIMITS.maxDimension}.`);
      string(border.style, `${sideLabel}.style`, 50);
    }
  }
  if (paint.radius !== undefined) tuple(paint.radius, `nodes[${index}].paint.radius`, 0);
  optionalNumber(paint.opacity, `nodes[${index}].paint.opacity`, 0, 1);
  optionalString(paint.boxShadow, `nodes[${index}].paint.boxShadow`, 2_000);
  enumValue(paint.overflow, `nodes[${index}].paint.overflow`, ["visible", "hidden", "clip"]);
  // The per-axis values are diagnostic detail rather than an importer switch,
  // so they are bounded as strings instead of restricted to a fixed set.
  optionalString(paint.overflowX, `nodes[${index}].paint.overflowX`, 50);
  optionalString(paint.overflowY, `nodes[${index}].paint.overflowY`, 50);
}

function validateLayout(value: unknown, index: number): void {
  const layout = record(value, `nodes[${index}].layout`);
  enumValue(string(layout.kind, `nodes[${index}].layout.kind`, 20), `nodes[${index}].layout.kind`, ["none", "flex", "grid"]);
  enumValue(layout.direction, `nodes[${index}].layout.direction`, ["row", "row-reverse", "column", "column-reverse"]);
  enumValue(layout.wrap, `nodes[${index}].layout.wrap`, ["wrap", "nowrap"]);
  optionalString(layout.justifyContent, `nodes[${index}].layout.justifyContent`, 100);
  optionalString(layout.alignItems, `nodes[${index}].layout.alignItems`, 100);
  optionalNumber(layout.rowGap, `nodes[${index}].layout.rowGap`, 0, SCENE_LIMITS.maxDimension);
  optionalNumber(layout.columnGap, `nodes[${index}].layout.columnGap`, 0, SCENE_LIMITS.maxDimension);
  if (layout.padding !== undefined) tuple(layout.padding, `nodes[${index}].layout.padding`, 0);
  optionalBoolean(layout.absolute, `nodes[${index}].layout.absolute`);
  optionalBoolean(layout.positioned, `nodes[${index}].layout.positioned`);
}

function validateTextStyle(value: unknown, index: number): void {
  const style = record(value, `nodes[${index}].textStyle`);
  string(style.fontFamily, `nodes[${index}].textStyle.fontFamily`, 500);
  const fontSize = number(style.fontSize, `nodes[${index}].textStyle.fontSize`, 0.01);
  if (fontSize > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].textStyle.fontSize must be no greater than ${SCENE_LIMITS.maxDimension}.`);
  const fontWeight = number(style.fontWeight, `nodes[${index}].textStyle.fontWeight`, 1);
  if (fontWeight > 1_000) fail(`nodes[${index}].textStyle.fontWeight must be no greater than 1000.`);
  string(style.fontStyle, `nodes[${index}].textStyle.fontStyle`, 50);
  const lineHeight = number(style.lineHeight, `nodes[${index}].textStyle.lineHeight`, 0.01);
  if (lineHeight > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].textStyle.lineHeight must be no greater than ${SCENE_LIMITS.maxDimension}.`);
  const letterSpacing = number(style.letterSpacing, `nodes[${index}].textStyle.letterSpacing`, -SCENE_LIMITS.maxDimension);
  if (letterSpacing > SCENE_LIMITS.maxDimension) fail(`nodes[${index}].textStyle.letterSpacing must be no greater than ${SCENE_LIMITS.maxDimension}.`);
  string(style.textAlign, `nodes[${index}].textStyle.textAlign`, 50);
  string(style.textDecoration, `nodes[${index}].textStyle.textDecoration`, 100);
  string(style.textTransform, `nodes[${index}].textStyle.textTransform`, 50);
}

function validateAsset(value: unknown, index: number): asserts value is AssetRef {
  const asset = record(value, `assets[${index}]`);
  string(asset.id, `assets[${index}].id`, 200);
  optionalString(asset.url, `assets[${index}].url`, 2_000_000);
  optionalString(asset.dataUrl, `assets[${index}].dataUrl`, 20_000_000);
  optionalString(asset.mimeType, `assets[${index}].mimeType`, 200);
  optionalNumber(asset.width, `assets[${index}].width`, 0, SCENE_LIMITS.maxDimension);
  optionalNumber(asset.height, `assets[${index}].height`, 0, SCENE_LIMITS.maxDimension);
  if ((typeof asset.url !== "string" || !asset.url.trim()) && (typeof asset.dataUrl !== "string" || !asset.dataUrl.trim())) {
    fail(`assets[${index}] must include a non-empty url or dataUrl.`);
  }
}

function validateDiagnostic(value: unknown, index: number): void {
  const diagnostic = record(value, `diagnostics[${index}]`);
  enumValue(string(diagnostic.severity, `diagnostics[${index}].severity`, 20), `diagnostics[${index}].severity`, ["info", "warning", "error"]);
  string(diagnostic.code, `diagnostics[${index}].code`, 100);
  string(diagnostic.message, `diagnostics[${index}].message`, 2_000);
export const PROTOCOL_VERSION = 1 as const;

export type ScriptPolicy = "off" | "trusted";
export type Severity = "info" | "warning" | "error";
export type SceneKind = "container" | "box" | "text" | "image" | "svg" | "fallback";
export type LayoutKind = "none" | "flex" | "grid";

export interface ViewportSpec {
  id: string;
  name: string;
  width: number;
  height: number;
}

export const DEFAULT_VIEWPORTS: ViewportSpec[] = [
  { id: "desktop", name: "Desktop", width: 1440, height: 900 },
  { id: "tablet", name: "Tablet", width: 768, height: 1024 },
  { id: "mobile", name: "Mobile", width: 390, height: 844 }
];

export interface CaptureRequest {
  protocolVersion: typeof PROTOCOL_VERSION;
  html: string;
  baseUrl?: string;
  viewports: ViewportSpec[];
  scriptPolicy: ScriptPolicy;
  settleDelayMs: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface SceneBorder {
  color: string;
  width: number;
  style: string;
}

export interface SceneBorders {
  top: SceneBorder;
  right: SceneBorder;
  bottom: SceneBorder;
  left: SceneBorder;
}

export interface ScenePaint {
  backgroundColor?: string;
  backgroundImage?: string;
  /** Computed CSS background placement retained for asset materialization and diagnostics. */
  backgroundRepeat?: string;
  backgroundRepeatX?: string;
  backgroundRepeatY?: string;
  backgroundSize?: string;
  backgroundPosition?: string;
  backgroundPositionX?: string;
  backgroundPositionY?: string;
  color?: string;
  borderColor?: string;
  borderWidth?: number;
  borderStyle?: string;
  /** All computed sides when their color, width, or style differs. Uniform
   * borders keep the legacy borderColor/borderWidth/borderStyle fields. */
  borders?: SceneBorders;
  radius?: [number, number, number, number];
  opacity?: number;
  boxShadow?: string;
  /** Effective clipping, set only when both axes clip; Penpot containers cannot clip one axis alone. */
  overflow?: "visible" | "hidden" | "clip";
  /** Computed per-axis CSS overflow, retained so single-axis clipping can be diagnosed rather than guessed at. */
  overflowX?: string;
  overflowY?: string;
}

export interface TextStyle {
  fontFamily: string;
  fontSize: number;
  fontWeight: number;
  fontStyle: string;
  /** Unitless line-height multiplier used by Penpot (for example, 1.35). */
  lineHeight: number;
  letterSpacing: number;
  textAlign: string;
  textDecoration: string;
  textTransform: string;
}

export interface SceneLayout {
  kind: LayoutKind;
  direction?: "row" | "row-reverse" | "column" | "column-reverse";
  wrap?: "wrap" | "nowrap";
  justifyContent?: string;
  alignItems?: string;
  rowGap?: number;
  columnGap?: number;
  padding?: [number, number, number, number];
  absolute?: boolean;
  /** True when CSS position is not static. Positioned elements with an
   * automatic or zero z-index paint above non-positioned in-flow content. */
  positioned?: boolean;
}

export interface AssetRef {
  id: string;
  url?: string;
  dataUrl?: string;
  mimeType?: string;
  width?: number;
  height?: number;
}

export interface SceneImagePositionAxis {
  /** Fraction of the space remaining after sizing the image; 0.5 centers it.
   * CSS positions outside the 0..1 interval are valid. */
  percentage: number;
  /** Additional offset in captured page pixels, after any uniform transform. */
  offset: number;
}

export interface SceneImageFit {
  fit: "fill" | "contain" | "cover" | "none" | "scale-down";
  position: { x: SceneImagePositionAxis; y: SceneImagePositionAxis };
  /** Browser natural dimensions in CSS pixels, including srcset density
   * correction. These remain unchanged by CSS transforms. */
  intrinsicWidth: number;
  intrinsicHeight: number;
  /** Uniform CSS transform scale. Defaults to 1 for older scene producers. */
  scale?: number;
}

export interface SceneNode {
  id: string;
  parentId?: string;
  children: string[];
  kind: SceneKind;
  name: string;
  source: string;
  /** Captured box in page pixels. For a transformed layer this is the layer's
   * own (scaled) size plus the position of its top-left corner after every
   * CSS transform; see `rotation`. */
  rect: Rect;
  /** Clockwise rotation in degrees (the CSS convention) about the top-left
   * corner of `rect`. Absent when no transform rotates the layer. */
  rotation?: number;
  /** Effective integer z-index. `z-index: auto` is stored as 0 (its paint
   * position for positioned elements) with `zIndexAuto` set, so explicit
   * numeric zero stays distinct from automatic stacking. */
  zIndex: number;
  /** True when the computed CSS z-index is `auto` rather than numeric. */
  zIndexAuto?: boolean;
  paint: ScenePaint;
  layout: SceneLayout;
  text?: string;
  /** Keep a captured source line on one line when imported. */
  textNoWrap?: boolean;
  /** Horizontal fit scale for a captured line that exceeds its source bounds. */
  textFitScale?: number;
  /** Right-edge space available to a non-wrapping captured text line. */
  textMaxWidth?: number;
  textStyle?: TextStyle;
  assetId?: string;
  /** Replaced image sizing inside the content box (border and padding excluded).
   * Absent for legacy scenes or images without usable natural dimensions. */
  image?: SceneImageFit;
  fallbackReason?: string;
}

export interface Diagnostic {
  severity: Severity;
  code: string;
  message: string;
  viewportId?: string;
  source?: string;
}

export interface SceneDocument {
  protocolVersion: typeof PROTOCOL_VERSION;

