function validateImage(value: unknown, index: number): void {
  const label = `nodes[${index}].image`;
  const image = record(value, label);
  enumValue(string(image.fit, `${label}.fit`, 30), `${label}.fit`, ["fill", "contain", "cover", "none", "scale-down"]);
